"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[2212],{7576(e){e.exports=JSON.parse('{"tag":{"label":"graph-theory","permalink":"/azeon/p-vs-np/tags/graph-theory","allTagsPath":"/azeon/p-vs-np/tags","count":2,"items":[{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"}],"unlisted":false}}')}}]);